/* generated by build/make_classic.py — classic build, do not hand-edit */
(function(){
"use strict";
const THREE = window.THREE;
const $ = id => document.getElementById(id);
const body = document.body;
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;

const roomData = [
  { z: 2.4, name: '柔软的轮廓', en: 'SOFT SILHOUETTES' },
  { z: -5.6, name: '日常的秩序', en: 'EVERYDAY POISE' },
  { z: -13.6, name: '流动的边界', en: 'FLUID BOUNDARIES' }
];
const products = Atelier.products;
const rooms = [
  products.filter(p => p.room.startsWith('01')),
  products.filter(p => p.room.startsWith('02')),
  products.filter(p => p.room.startsWith('03'))
];

let scene, camera, renderer, model, modelFailed = false, ready = false;
const pickables = [];
const raycaster = new THREE.Raycaster();
const clock = new THREE.Clock();
const pointer = new THREE.Vector2();

// Nine fixed shots: each room has a doorway establishing shot plus one close
// shot per garment. Nothing moves continuously, so the visitor only ever
// chooses "next, previous, or this one".
const shots = [];
rooms.forEach((list, room) => {
  shots.push({ room, kind: 'door', product: null });
  list.forEach(p => shots.push({ room, kind: 'piece', product: products.indexOf(p) }));
});
const LAST = shots.length - 1;

let index = 3;          // 04 · 02 房总览，正对中间的房间
let anim = null;
let live = false;

const PANEL_X = 8.97;
const PANEL_DZ = 1.24;

function layout() {
  return innerWidth < 620
    ? { doorX: 2.45, pieceX: 5.05, doorFov: 82, pieceFov: 70, dolly: .10, doorPitch: .10 }
    : { doorX: 4.90, pieceX: 6.62, doorFov: 60, pieceFov: 64, dolly: .22, doorPitch: .045 };
}

function shotPose(i) {
  const shot = shots[i];
  const L = layout();
  const center = roomData[shot.room].z;
  const push = live ? L.dolly : 0;
  if (shot.kind === 'door') {
    return { x: L.doorX + push, y: 1.70, z: center, pitch: L.doorPitch, fov: L.doorFov };
  }
  const order = rooms[shot.room].indexOf(products[shot.product]);
  return {
    x: L.pieceX + push * .5, y: 1.80,
    z: center + (order === 0 ? -PANEL_DZ : PANEL_DZ),
    pitch: .045, fov: L.pieceFov
  };
}

function progress(value) {
  const n = Math.max(0, Math.min(100, Math.round(value)));
  $('loadPercent').textContent = n + '%';
  $('loadBar').style.width = n + '%';
}
function loaded() {
  progress(100);
  setTimeout(() => { $('loader').classList.add('is-done'); }, reduced ? 80 : 520);
}

function applyPose(pose) {
  if (!camera) return;
  camera.position.set(pose.x, pose.y, pose.z);
  camera.rotation.set(pose.pitch, -Math.PI / 2, 0, 'YXZ');
  if (Math.abs(camera.fov - pose.fov) > .001) {
    camera.fov = pose.fov;
    camera.updateProjectionMatrix();
  }
}

const easeInOut = t => (t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const smoothstep = (a, b, t) => {
  const x = Math.max(0, Math.min(1, (t - a) / (b - a)));
  return x * x * (3 - 2 * x);
};

function poseNow() {
  return { x: camera.position.x, y: camera.position.y, z: camera.position.z, pitch: camera.rotation.x, fov: camera.fov };
}

function setVeil(value) {
  const el = $('stageVeil');
  if (el) el.style.opacity = value.toFixed(3);
}

function applyLerp(a, b, e) {
  camera.position.set(a.x + (b.x - a.x) * e, a.y + (b.y - a.y) * e, a.z + (b.z - a.z) * e);
  camera.rotation.set(a.pitch + (b.pitch - a.pitch) * e, -Math.PI / 2, 0, 'YXZ');
  const fov = a.fov + (b.fov - a.fov) * e;
  if (Math.abs(camera.fov - fov) > .01) { camera.fov = fov; camera.updateProjectionMatrix(); }
}

// A transition is a queue of moves. Each move can carry its own veil curve, so
// the swap between two sealed rooms always happens behind full paper.
function play(moves) {
  if (!camera) return;
  if (reduced) {
    applyPose(moves[moves.length - 1].to);
    setVeil(0);
    anim = null;
    return;
  }
  anim = { moves: moves.slice(), move: moves[0], from: poseNow(), t: 0 };
}

function tickAnim(dt) {
  const move = anim.move;
  anim.t = Math.min(1, anim.t + dt / move.duration);
  const t = anim.t;
  applyLerp(anim.from, move.to, easeInOut(t));
  if (move.veil === 'in') setVeil(smoothstep(0, .84, t));
  else if (move.veil === 'out') setVeil(1 - smoothstep(.2, .94, t));
  else setVeil(0);
  if (t < 1) return;
  anim.moves.shift();
  if (move.end) move.end();
  if (!anim.moves.length) { anim = null; setVeil(0); return; }
  anim.move = anim.moves[0];
  anim.from = poseNow();
  anim.t = 0;
}

function goTo(i) {
  const target = Math.max(0, Math.min(LAST, i));
  const from = index;
  if (target === from) return;
  const dir = target > from ? 1 : -1;
  const crossing = shots[target].room !== shots[from].room;
  const oldPose = shotPose(from);
  index = target;
  if (!camera) { updateChrome(); return; }
  if (reduced) { updateChrome(); applyPose(shotPose(index)); setVeil(0); anim = null; return; }
  const entry = shotPose(index);
  if (!crossing) { updateChrome(); play([{ to: entry, duration: .8 }]); return; }
  // Each room is a sealed box: interpolating straight from one doorway to the
  // next would drive the camera through two walls, which is the black tearing.
  // Advance into the artwork wall instead, swap behind paper, then ease out of
  // a pulled-back pose so the arrival still reads as moving forward.
  // Rooms run towards -z, so travel is -dir on the z axis. Sliding that way
  // while the screen washes to paper keeps a sense of going somewhere, even
  // though the two spaces are never actually connected.
  const push = .55 * dir;
  const drift = .5 * -dir;
  play([
    {
      to: { ...oldPose, x: oldPose.x + push, z: oldPose.z + drift },
      duration: .42, veil: 'in',
      // The label and buy bar swap exactly when the paper is at full, never
      // while the previous room is still on screen.
      end: () => { applyPose({ ...entry, x: entry.x - push, z: entry.z - drift }); updateChrome(); }
    },
    { to: entry, duration: .72, veil: 'out' }
  ]);
}

function setLive(value) {
  if (live === value) return;
  live = value;
  body.classList.toggle('is-live', live);
  if (camera && !anim) play([{ to: shotPose(index), duration: .9 }]);
}

function step(delta) {
  if (modelFailed) return;
  if (delta > 0 && index === LAST) { setLive(false); return; }
  if (delta < 0 && index === 0) { setLive(false); return; }
  setLive(true);
  goTo(index + delta);
}

function changeRoom(delta) {
  if (modelFailed) return;
  setLive(true);
  const room = shots[index].room;
  const next = (room + delta + roomData.length) % roomData.length;
  goTo(next * 3);
}

function updateChrome() {
  const shot = shots[index];
  $('shotIndex').textContent = String(index + 1).padStart(2, '0');
  $('stageRoom').textContent = '0' + (shot.room + 1) + ' ' + roomData[shot.room].name;
  $('stageRoom').dataset.en = roomData[shot.room].en;
  const isPiece = shot.kind === 'piece';
  $('stageBack').hidden = !isPiece;
  $('stageBuy').hidden = !isPiece;
  if (isPiece) {
    const product = products[shot.product];
    $('buyName').textContent = product.name;
    $('buyPrice').textContent = Atelier.money(product.price);
    $('buyLink').href = 'product.html?id=' + product.id;
  }
}

function render() {
  requestAnimationFrame(render);
  if (!camera) return;
  const dt = Math.min(clock.getDelta(), .12);
  // Advance by real time: a slow device must not stretch a move.
  if (anim) tickAnim(dt);
  renderer.render(scene, camera);
}

function hitTest(event) {
  if (!ready || !pickables.length) return;
  const rect = renderer.domElement.getBoundingClientRect();
  pointer.set((event.clientX - rect.left) / rect.width * 2 - 1, -(event.clientY - rect.top) / rect.height * 2 + 1);
  raycaster.setFromCamera(pointer, camera);
  const hits = raycaster.intersectObjects(model.children, true);
  if (!hits.length || hits[0].distance > 14) return;
  const found = hits[0].object.userData.productIndex;
  if (!Number.isInteger(found)) return;
  const shot = shots[index];
  // Close shot: clicking the piece in front of you opens the buy panel,
  // clicking its neighbour steps across to that piece.
  if (shot.kind === 'piece' && shot.product === found) { openProduct(products[found]); return; }
  const wanted = shots.findIndex(s => s.kind === 'piece' && s.product === found);
  if (wanted >= 0) { setLive(true); goTo(wanted); }
}

function loadEmbeddedModel() {
  return new Promise((resolve, reject) => {
    const decode = () => {
      const data = window.HALL_MODEL_DATA;
      const bin = atob(data.slice(data.indexOf(',') + 1));
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      resolve(bytes.buffer);
    };
    if (window.HALL_MODEL_DATA) { decode(); return; }
    const tag = document.createElement('script');
    tag.src = 'js/hall-model.js';
    tag.onload = decode;
    tag.onerror = () => reject(new Error('embedded model payload missing'));
    document.head.appendChild(tag);
  });
}

function init() {
  try {
    renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
  } catch (e) { staticGallery(); return; }
  renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.domElement.addEventListener('webglcontextlost', e => { e.preventDefault(); staticGallery(); }, { once: true });
  renderer.domElement.setAttribute('aria-label', '可切换机位的三维女装展厅');
  $('scene').appendChild(renderer.domElement);

  scene = new THREE.Scene();
  scene.background = new THREE.Color('#efede9');
  camera = new THREE.PerspectiveCamera(60, 1, .06, 90);
  camera.rotation.order = 'YXZ';
  resize();

  const onModel = gltf => {
    model = gltf.scene;
    // glTF exports Blender coordinates (x, y, z) as (x, z, -y).
    model.rotation.x = Math.PI / 2;
    scene.add(model);
    model.traverse(obj => {
      if (!obj.isMesh) return;
      const found = products.findIndex(p => obj.name === p.node || obj.name === 'Product_' + p.id + 'jpg');
      if (found >= 0) { obj.userData.productIndex = found; pickables.push(obj); }
      if (!obj.material) return;
      obj.material.toneMapped = false;
      if (obj.material.map) obj.material.map.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
    });
    ready = true;
    loaded();
    applyPose(shotPose(index));
    window.galleryDebug = { scene, camera, renderer, model, shots, pickables, state: () => ({ index, live, busy: !!anim }) };
  };
  const onProgress = xhr => progress(8 + (xhr.total ? xhr.loaded / xhr.total * 88 : Math.min(65, xhr.loaded / 80000)));
  const onError = err => { console.error('Gallery model could not be loaded.', err); staticGallery(); };

  // A page opened by double-click cannot fetch a neighbouring file, so the
  // model travels as base64 and is decoded in place instead of downloaded.
  if (location.protocol === 'file:') {
    progress(12);
    loadEmbeddedModel().then(buffer => {
      progress(55);
      new THREE.GLTFLoader().parse(buffer, '', onModel, onError);
    }).catch(onError);
  } else {
    new THREE.GLTFLoader().load('models/hall.glb', onModel, onProgress, onError);
  }

  initDrawer();
  initInput();
  updateChrome();
  render();
  addEventListener('resize', resize);
  // The stage box grows when the visitor first interacts, so the drawing buffer
  // has to follow its own size rather than only the window size.
  let resizeQueued = false;
  new ResizeObserver(() => {
    if (resizeQueued) return;
    resizeQueued = true;
    requestAnimationFrame(() => { resizeQueued = false; resize(); });
  }).observe($('stage'));
}

function resize() {
  if (!renderer || !camera) return;
  const box = $('stage').getBoundingClientRect();
  camera.aspect = Math.max(.35, box.width / Math.max(1, box.height));
  camera.updateProjectionMatrix();
  renderer.setSize(box.width, box.height, false);
  if (ready && !anim) applyPose(shotPose(index));
}

function staticGallery() {
  modelFailed = true;
  const el = $('scene');
  el.style.background = 'url("img/coat-camel.jpg") center 38% / cover no-repeat';
  el.style.filter = 'saturate(.7)';
  loaded();
  $('prevShot').hidden = true;
  $('nextShot').hidden = true;
  $('stageHint').innerHTML = '此设备暂不支持 3D 展厅 · <a href="products.html">浏览全部六件作品</a>';
}

function initInput() {
  const stage = $('stage');
  $('prevShot').addEventListener('click', () => changeRoom(-1));
  $('nextShot').addEventListener('click', () => changeRoom(1));
  $('stageBack').addEventListener('click', () => { setLive(true); goTo(shots[index].room * 3); });

  let locked = 0;
  stage.addEventListener('wheel', e => {
    if ($('productDrawer').open) return;
    if (Math.abs(e.deltaY) < 3) return;
    const down = e.deltaY > 0;
    if (down && index === LAST) {
      // Let the page scroll reach the editorial underneath.
      setLive(false);
      return;
    }
    if (!down && index === 0) return;
    e.preventDefault();
    const now = performance.now();
    if (now - locked < 340) return;
    locked = now;
    step(down ? 1 : -1);
  }, { passive: false });

  // A click only counts if the pointer stayed put; dragging across the canvas
  // must never fire a product action.
  let downX = 0, downY = 0;
  stage.addEventListener('pointerdown', e => { downX = e.clientX; downY = e.clientY; });
  stage.addEventListener('click', e => {
    if (e.target.closest('button, a')) return;
    if (Math.hypot(e.clientX - downX, e.clientY - downY) > 8) return;
    hitTest(e);
  });

  addEventListener('keydown', e => {
    if ($('productDrawer').open) return;
    if (e.key === 'ArrowLeft') { e.preventDefault(); changeRoom(-1); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); changeRoom(1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); step(-1); }
    else if (e.key === 'ArrowDown') { e.preventDefault(); step(1); }
  });

  // Horizontal swipe changes room; vertical gestures stay with the page so the
  // editorial below is always reachable by scrolling.
  let startX = null, startY = null;
  stage.addEventListener('touchstart', e => {
    if (e.touches.length !== 1) return;
    startX = e.touches[0].clientX; startY = e.touches[0].clientY;
  }, { passive: true });
  stage.addEventListener('touchend', e => {
    if (startX === null || !e.changedTouches.length) return;
    const dx = e.changedTouches[0].clientX - startX;
    const dy = e.changedTouches[0].clientY - startY;
    startX = startY = null;
    if (Math.abs(dx) > 48 && Math.abs(dx) > Math.abs(dy) * 1.4) changeRoom(dx < 0 ? 1 : -1);
  }, { passive: true });

  // Once the stage has scrolled mostly out of view it folds back to a frame.
  let ticking = false;
  addEventListener('scroll', () => {
    if (ticking || !live) return;
    ticking = true;
    requestAnimationFrame(() => {
      ticking = false;
      const box = $('stage').getBoundingClientRect();
      if (box.bottom < innerHeight * .55) setLive(false);
    });
  }, { passive: true });
}

function initDrawer() {
  let product;
  window.openProduct = p => {
    product = p;
    $('drawerImage').src = p.image; $('drawerImage').alt = p.name;
    $('drawerRoom').textContent = p.room + ' · ' + p.en;
    $('drawerName').textContent = p.name; $('drawerPrice').textContent = Atelier.money(p.price);
    $('drawerDescription').textContent = p.description;
    $('drawerLink').href = 'product.html?id=' + p.id;
    $('drawerAdd').innerHTML = '加入购物袋 · ' + Atelier.money(p.price) + ' <span>＋</span>';
    if (!$('productDrawer').open) $('productDrawer').showModal();
  };
  $('drawerClose').addEventListener('click', () => $('productDrawer').close());
  $('productDrawer').addEventListener('click', e => {
    if (e.target !== $('productDrawer')) return;
    const r = $('productDrawer').getBoundingClientRect();
    if (e.clientX < r.left) $('productDrawer').close();
  });
  $('drawerAdd').addEventListener('click', () => {
    if (!product) return;
    Atelier.bag.add(product.id, $('drawerSize').value, 1);
    $('productDrawer').close();
  });
  $('buyAdd').addEventListener('click', () => {
    const shot = shots[index];
    if (shot.kind !== 'piece') return;
    Atelier.bag.add(products[shot.product].id, 'M', 1);
  });
}

progress(4);
init();

})();
